#!/usr/bin/env node
// Generated by Keel — opt-in SessionStart hook: one line when a newer keel is published.
// Read-only: reads .keel/meta.json, makes one GET for keel's published release.json, writes nothing.
// Speaks only when a USER-facing release is newer than this project ("latest" in release.json);
// releases marked internal never trigger it. Names the version /plugin install would give.
// Sends nothing beyond that request. Silent when offline, slow (2s), or disabled.
// Disable: KEEL_NO_UPDATE_CHECK=1, or "updateCheck": false in .keel/meta.json.
// Self-test: node .claude/hooks/keel-update-check.mjs --self-test
import { readFileSync } from 'fs'

const URL = 'https://raw.githubusercontent.com/achatt89/keel/main/release.json'

// true when a (x.y.z) is newer than b; pre-release suffixes ignored
export const newer = (a, b) => {
  const p = v => String(v).split('-')[0].split('.').map(n => parseInt(n, 10) || 0)
  const [x, y] = [p(a), p(b)]
  for (let i = 0; i < 3; i++) if ((x[i] || 0) !== (y[i] || 0)) return (x[i] || 0) > (y[i] || 0)
  return false
}

// The one line to show, or null. feed = release.json ({version, latest}); an old feed without
// "latest" counts every release as user-facing.
export const notice = (feed, onVersion) => {
  const latest = feed.latest || feed.version
  if (!latest || !newer(latest, onVersion)) return null
  return `keel ${feed.version} available${feed.version !== latest ? ` (user-facing changes up to ${latest})` : ''} — this project is on ${onVersion}; run /plugin marketplace update thelogicatelier, then /keel upgrade`
}

if (process.argv.includes('--self-test')) {
  const ok = newer('2.1.0', '2.0.0') && newer('10.0.0', '9.9.9') && !newer('2.0.0', '2.0.0') &&
    !newer('1.9.9', '2.0.0') && newer('2.0.1', '2.0.0-beta') &&
    notice({ version: '2.5.2', latest: '2.4.3' }, '2.4.3') === null &&             // internal-only gap: silent
    /keel 2\.5\.2 available \(user-facing changes up to 2\.4\.3\)/.test(notice({ version: '2.5.2', latest: '2.4.3' }, '2.4.0')) &&
    /^keel 2\.6\.0 available —/.test(notice({ version: '2.6.0', latest: '2.6.0' }, '2.5.2')) &&
    notice({ version: '2.1.0' }, '2.0.0') !== null && notice({ version: '2.0.0' }, '2.0.0') === null
  console.log(ok ? 'ok' : 'FAIL'); process.exit(ok ? 0 : 1)
}

if (process.env.KEEL_NO_UPDATE_CHECK) process.exit(0)
let meta
try { meta = JSON.parse(readFileSync('.keel/meta.json', 'utf8')) } catch { process.exit(0) }
if (meta.updateCheck === false || !meta.keelVersion) process.exit(0)

try {
  const res = await fetch(URL, { signal: AbortSignal.timeout(2000) })
  const msg = res.ok ? notice(await res.json(), meta.keelVersion) : null
  if (msg) process.stdout.write(JSON.stringify({ systemMessage: msg }))
} catch {}
process.exit(0)
